cat > tests/test_rounding.py <<'EOF'
import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import label_span, round_labels, round_span


class RoundSpanTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        span = round_span(parse_span("09:07-17:08"), 15)
        self.assertEqual(span, parse_span("09:00-17:15"))

    def test_halfway_goes_up(self):
        self.assertEqual(round_span(Span(67, 128), 15), Span(60, 135))

    def test_end_of_day_stays_valid(self):
        self.assertEqual(round_span(Span(60, 1439), 30), Span(60, 1440))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(61, 63), 15)


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels([Span(0, 600)], step)

    def test_good_steps_work(self):
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(len(round_labels([Span(0, 600)], step)), 1)


class LabelTests(unittest.TestCase):
    def test_label(self):
        self.assertEqual(label_span(parse_span("09:00-17:15")), "09:00-17:15 (8h 15m)")

    def test_label_under_an_hour(self):
        self.assertEqual(label_span(parse_span("09:00-09:30")), "09:00-09:30 (0h 30m)")

    def test_round_labels_keeps_order(self):
        spans = [parse_span("13:02-17:14"), parse_span("08:58-12:01")]
        self.assertEqual(
            round_labels(spans, 15),
            ["13:00-17:15 (4h 15m)", "09:00-12:00 (3h 0m)"]
        )

    def test_empty(self):
        self.assertEqual(round_labels([], 15), [])


if __name__ == "__main__":
    unittest.main()
